<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {api,day,fmt,json,today} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import AppModal from '@/components/AppModal.vue';import EmptyState from '@/components/EmptyState.vue';const tab=ref<'ads'|'withdrawals'>('ads'),ads=ref<any[]>([]),withdrawals=ref<any[]>([]),sites=ref<any[]>([]),open=ref(false),editing=ref<any>(),form=reactive<any>({});async function load(){[ads.value,withdrawals.value,sites.value]=await Promise.all([api('/ads'),api('/withdrawals'),api('/sites')])}function show(x?:any){editing.value=x;Object.assign(form,x?{...x,date:String(x.expenseDate||x.withdrawalDate).slice(0,10)}:{date:today(),siteId:sites.value[0]?.id,amount:0,fee:0,channel:'',notes:''});open.value=true}async function save(){const base=tab.value==='ads'?'ads':'withdrawals';await api(editing.value?`/${base}/${editing.value.id}`:`/${base}`,json(editing.value?'PATCH':'POST',form));open.value=false;load()}async function del(x:any){if(confirm('确定删除该流水？')){await api(`/${tab.value}/${x.id}`,{method:'DELETE'});load()}}onMounted(load)</script>
<template><PageHeader title="广告与提现" subtitle="广告计入期间费用，提现仅作为资金划转记录"><el-button type="primary" @click="show()">新增{{tab==='ads'?'广告费用':'提现记录'}}</el-button></PageHeader><el-tabs v-model="tab" type="card"><el-tab-pane label="广告投入" name="ads"/><el-tab-pane label="提现流水" name="withdrawals"/></el-tabs><el-card shadow="never"><el-table v-if="tab==='ads'" :data="ads" stripe empty-text="暂无广告流水"><el-table-column label="日期"><template #default="{row}">{{day(row.expenseDate)}}</template></el-table-column><el-table-column label="站点" prop="site.name"/><el-table-column label="渠道"><template #default="{row}">{{row.channel||'—'}}</template></el-table-column><el-table-column label="金额"><template #default="{row}"><b>¥ {{fmt(row.amount)}}</b></template></el-table-column><el-table-column prop="notes" label="备注" show-overflow-tooltip/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row)">编辑</el-button><el-button link type="danger" @click="del(row)">删除</el-button></template></el-table-column></el-table><el-table v-else :data="withdrawals" stripe empty-text="暂无提现流水"><el-table-column label="日期"><template #default="{row}">{{day(row.withdrawalDate)}}</template></el-table-column><el-table-column label="站点" prop="site.name"/><el-table-column label="提现金额"><template #default="{row}"><b>¥ {{fmt(row.amount)}}</b></template></el-table-column><el-table-column label="手续费"><template #default="{row}">¥ {{fmt(row.fee)}}</template></el-table-column><el-table-column prop="notes" label="备注" show-overflow-tooltip/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row)">编辑</el-button><el-button link type="danger" @click="del(row)">删除</el-button></template></el-table-column></el-table></el-card><AppModal :open="open" :title="editing?'编辑流水':'新增流水'" @close="open=false"><el-form :model="form" label-position="top" @submit.prevent="save"><div class="grid gap-x-4 sm:grid-cols-2"><el-form-item label="日期" required><el-date-picker v-model="form.date" type="date" value-format="YYYY-MM-DD" class="!w-full"/></el-form-item><el-form-item label="站点" required><el-select v-model="form.siteId" class="w-full"><el-option v-for="s in sites" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="金额（CNY）"><el-input-number v-model="form.amount" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item><el-form-item v-if="tab==='ads'" label="渠道"><el-input v-model="form.channel" placeholder="如 Shopee Ads"/></el-form-item><el-form-item v-else label="手续费（CNY）"><el-input-number v-model="form.fee" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item></div><el-form-item label="备注"><el-input v-model="form.notes" type="textarea"/></el-form-item><div class="flex justify-end gap-2"><el-button @click="open=false">取消</el-button><el-button type="primary" native-type="submit">保存</el-button></div></el-form></AppModal></template>
